from collections import deque
from copy import deepcopy

class Solution:

	def BFS(self, G, parent, s, t):
		n = len(G)
		visited = [False for _ in range(n)]
		queue = deque()
		queue.append(s)
		visited[s] = True
		while queue:
			vertex = queue.popleft()
			for neighbour in range(n):
				if visited[neighbour] == False and G[vertex][neighbour] > 0:
					queue.append(neighbour)
					visited[neighbour] = True
					parent[neighbour] = vertex
					if neighbour == t:
						return True
		return False

	def augmentThePath(self, G, parent, vertex):
		bottleNeck = float('inf')
		helpVariable = vertex
		while parent[vertex] != None:
			bottleNeck = min(bottleNeck, G[parent[vertex]][vertex])
			vertex = parent[vertex]
		vertex = helpVariable
		while parent[vertex] != None:
			G[parent[vertex]][vertex] -= bottleNeck
			G[vertex][parent[vertex]] += bottleNeck
			vertex = parent[vertex]
		return bottleNeck

	def FordFulkerson(self, M, s, t):
		n = len(M)
		maxFlow = 0
		parent = [None for _ in range(n)]
		while self.BFS(M, parent, s, t):
			bottleNeck = self.augmentThePath(M, parent, t)
			maxFlow += bottleNeck
		return maxFlow

	def createVertices(self, Graph):
		n = len(Graph[0])
		m = len(Graph)
		size = n + m + 2
		G = [[0 for _ in range(n + m + 2)] for _ in range(n + m + 2)]
		for guy in range(m):
			G[size - 2][guy] = 1
			for machine in range(n):
				if Graph[guy][machine] == 1:
					G[guy][m + machine] = 1
		for machine in range(n):
			G[m + machine][size - 1] = 1
		return self.FordFulkerson(G, size - 2, size - 1)

	def maximumMatch(self, G):
		return self.createVertices(G)
